#!/usr/bin/env python3
# Generated by scripts/build-skill.mjs from scripts/skill/make_link.py in the drawcast repository (github.com/hmelberg/drawcast). Do not edit by hand: rebuild with `npm run build:skill`.
"""Print the drawcast.app link that plays a drawcast.

    python3 make_link.py cast.yaml
    python3 make_link.py < cast.yaml
    python3 make_link.py --base http://localhost:5199/ cast.yaml   (another player)

The link is https://www.drawcast.app/#cast=<data>: <data> is the UTF-8 text of the
YAML, compressed with raw DEFLATE (level 9, no zlib/gzip header) and written as
base64url without padding. Standard library only. make_link.mjs (Node) prints
the same link for the same file.
"""
import base64
import re
import sys
import zlib

BASE = "https://www.drawcast.app/"


def make_link(data: bytes, base: str = BASE) -> str:
    if data.startswith(b"\xef\xbb\xbf"):  # a byte-order mark is not part of the YAML
        data = data[3:]
    data.decode("utf-8")  # fail loudly on text that is not UTF-8
    c = zlib.compressobj(9, zlib.DEFLATED, -15)
    raw = c.compress(data) + c.flush()
    return base + "#cast=" + base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


# A drawcast script's own words (the app's src/spec/script/lines.ts and detect.ts): its column-0 settings, and the
# top-level keys only a YAML or JSON spec writes.
SETTING_RE = re.compile(
    r"^(lang|voice|level|record|feedback|affirm|heading|page|canvas|domain|vars|text|zoom_from|book|style|credits|board|use|with|adjust|details|sources|more|end_page|role|chapter|subtitle|advance|gap|transitions|next|enroll|prompt|comments|views|poster|tags|format|thumb|voices):(\s|$)"
)
SPEC_KEY_RE = re.compile(r"^(title|elements|commands|template|params|playlist|assets|subtitles|text_map|templates|audio)\s*:")


def spoken_lines(text: str) -> int:
    """How many spoken lines the drawcast has, near enough: a YAML spec's `speak:` fields, or a script's (.cast) speech lines."""
    speaks = len(re.findall(r'(?<![\w-])"?speak"?\s*:', text))
    if speaks > 0:
        return speaks
    n = script_lines(text)
    return n if n is not None else 0


def script_lines(text: str):
    """A script's speech lines: column 0, not a heading, setting, comment or goto, outside a fence. None when the text is no script."""
    fenced, ink, n = False, False, 0
    for raw in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        body = raw.strip()
        if body.startswith("```"):
            fenced = not fenced
            continue
        if fenced or body == "":
            continue
        if raw[:1] in (" ", "\t"):
            ink = True  # a stage direction
            continue
        if SPEC_KEY_RE.match(body):
            return None  # a YAML spec
        if re.match(r"^#{1,2}(\s|$)", body):
            ink = True
            continue
        if body.startswith("//") or re.match(r"^@[A-Za-z_][A-Za-z0-9_-]*$", body) or SETTING_RE.match(body):
            continue
        n += 1
    return n if ink else None


def main(argv):
    base = BASE
    args = list(argv)
    if "--base" in args:
        i = args.index("--base")
        base = args[i + 1]
        del args[i : i + 2]
    if args and args[0] != "-":
        with open(args[0], "rb") as f:
            data = f.read()
    else:
        data = sys.stdin.buffer.read()
    if not data.strip():
        sys.exit("make_link: no YAML given (a file name, or the YAML on stdin)")
    link = make_link(data, base)
    print(link)
    n = spoken_lines(data.decode("utf-8", "replace"))
    print(f"{n} spoken lines (the default brief is 14–20; a length the user asked for wins)", file=sys.stderr)
    if len(link) > 16000:
        print(
            f"note: the link is {len(link)} characters; if the chat cuts it, give the YAML and https://www.drawcast.app/#paste instead",
            file=sys.stderr,
        )


if __name__ == "__main__":
    main(sys.argv[1:])
